template:
% 参数由系统自动注入；斜四棱柱 ABCD-A'B'C'D'
% ABCD 为下底面平行四边形，A'B'C'D' 为上底面
% AA'、BB'、CC'、DD' 为互相平行的斜侧棱
% 实线：可见底面棱、上底面棱、可见侧棱
% 虚线：被遮挡的底面棱、上底面棱或侧棱
% 视觉归一化：把图形最长外接尺寸缩放到约 6 个坐标单位

% ==========================================================
% 斜四棱柱透视参数
% ==========================================================

% 底面 ABCD：AB 为主方向，AD 为副方向
% B、C 相对于 A、D 向右展开
\pgfmathsetmacro{\Ax}{-2.0 * \basex}
\pgfmathsetmacro{\Ay}{-0.9 * \basey}

\pgfmathsetmacro{\Bx}{\Ax + 1.0 * \basex}
\pgfmathsetmacro{\By}{\Ay}

% AD 方向采用倾斜透视表示
\pgfmathsetmacro{\Dx}{\Ax + 0.55 * \basey}
\pgfmathsetmacro{\Dy}{\Ay + 0.65 * \basey}

\pgfmathsetmacro{\Cx}{\Bx + 0.55 * \basey}
\pgfmathsetmacro{\Cy}{\By + 0.65 * \basey}

% ==========================================================
% 上底面：整体沿同一斜侧棱方向平移
% ==========================================================

\pgfmathsetmacro{\Apx}{\Ax + \slantx}
\pgfmathsetmacro{\Apy}{\Ay + \slanty}

\pgfmathsetmacro{\Bpx}{\Bx + \slantx}
\pgfmathsetmacro{\Bpy}{\By + \slanty}

\pgfmathsetmacro{\Cpx}{\Cx + \slantx}
\pgfmathsetmacro{\Cpy}{\Cy + \slanty}

\pgfmathsetmacro{\Dpx}{\Dx + \slantx}
\pgfmathsetmacro{\Dpy}{\Dy + \slanty}

% ==========================================================
% 视觉归一化
% ==========================================================
\pgfmathsetmacro{\xmin}{min(\Ax,\Bx,\Cx,\Dx,\Apx,\Bpx,\Cpx,\Dpx)}
\pgfmathsetmacro{\xmax}{max(\Ax,\Bx,\Cx,\Dx,\Apx,\Bpx,\Cpx,\Dpx)}
\pgfmathsetmacro{\ymin}{min(\Ay,\By,\Cy,\Dy,\Apy,\Bpy,\Cpy,\Dpy)}
\pgfmathsetmacro{\ymax}{max(\Ay,\By,\Cy,\Dy,\Apy,\Bpy,\Cpy,\Dpy)}

\pgfmathsetmacro{\figscale}{6 / max(\xmax-\xmin,\ymax-\ymin)}

% ==========================================================
% 开始绘图
% ==========================================================
\begin{tikzpicture}[
    scale=\figscale,
    every node/.style={
        font=\small,
        fill=none,
        inner sep=1.5pt
    }
]

    % ======================================================
    % 八个顶点
    % ======================================================
    \coordinate (A)  at (\Ax,\Ay);
    \coordinate (B)  at (\Bx,\By);
    \coordinate (C)  at (\Cx,\Cy);
    \coordinate (D)  at (\Dx,\Dy);

    \coordinate (Ap) at (\Apx,\Apy);
    \coordinate (Bp) at (\Bpx,\Bpy);
    \coordinate (Cp) at (\Cpx,\Cpy);
    \coordinate (Dp) at (\Dpx,\Dpy);

    % ======================================================
    % 下底面
    % ======================================================
    % 可见底面边
    \draw[thick] (A) -- (B);
    \draw[thick] (B) -- (C);
    \draw[thick] (C) -- (D);

    % AD 为被遮挡底面边
    \ifnum\showhidden>0
        \draw[dashed,thick] (D) -- (A);
    \else
        \draw[thick] (D) -- (A);
    \fi

    % ======================================================
    % 上底面
    % ======================================================
    \draw[thick] (Ap) -- (Bp);
    \draw[thick] (Bp) -- (Cp);
    \draw[thick] (Cp) -- (Dp);
    \draw[thick] (Dp) -- (Ap);

    % ======================================================
    % 四条斜侧棱
    % ======================================================
    \draw[thick] (A) -- (Ap);
    \draw[thick] (B) -- (Bp);
    \draw[thick] (C) -- (Cp);

    % D-D' 位于后方时采用虚线
    \ifnum\showhidden>0
        \draw[dashed,thick] (D) -- (Dp);
    \else
        \draw[thick] (D) -- (Dp);
    \fi

    % ======================================================
    % 条件性辅助元素
    % ======================================================
    \ifnum\showaux>0
        % 底面两条对角线
        \draw[dashed,thick] (A) -- (C);
        \draw[dashed,thick] (B) -- (D);

        % 上底面对角线
        \draw[dashed,thick] (Ap) -- (Cp);
        \draw[dashed,thick] (Bp) -- (Dp);
    \fi

    % ======================================================
    % 顶点标签
    % ======================================================
    \ifnum\showverts>0
        \node[below left=3pt] at (A) {$A$};
        \node[below right=3pt] at (B) {$B$};
        \node[right=4pt] at (C) {$C$};
        \node[left=4pt] at (D) {$D$};

        \node[above left=3pt] at (Ap) {$A'$};
        \node[right=3pt] at (Bp) {$B'$};
        \node[right=4pt] at (Cp) {$C'$};
        \node[left=4pt] at (Dp) {$D'$};
    \fi

    % ======================================================
    % 辅助点
    % ======================================================
    \ifnum\showpoints>0
        % 底面 AB 中点 E
        \coordinate (E) at ($(A)!0.5!(B)$);
        % 侧棱 AA' 中点 F
        \coordinate (F) at ($(A)!0.5!(Ap)$);
        % 上底面 A'B' 中点 G
        \coordinate (G) at ($(Ap)!0.5!(Bp)$);

        \fill (E) circle [radius=1.6pt];
        \fill (F) circle [radius=1.6pt];
        \fill (G) circle [radius=1.6pt];

        \node[below=3pt] at (E) {$E$};
        \node[left=3pt] at (F) {$F$};
        \node[above=3pt] at (G) {$G$};
    \fi

\end{tikzpicture}
